CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS development_statuses (code text PRIMARY KEY, name text NOT NULL UNIQUE, sort_order integer NOT NULL, is_active boolean NOT NULL DEFAULT true, is_final boolean NOT NULL DEFAULT false, allowed_next_codes text[] NOT NULL DEFAULT '{}');
INSERT INTO development_statuses (code,name,sort_order,is_final) VALUES ('backlog','Backlog',1,false),('analytics','Аналитика',2,false),('ready_for_development','Готово к разработке',3,false),('development','Разработка',4,false),('testing','Тестирование',5,false),('ready_for_release','Готово к релизу',6,false),('release','Релиз',7,false),('closed','Закрыто',8,true) ON CONFLICT (code) DO NOTHING;
CREATE TABLE IF NOT EXISTS user_projection (user_id uuid PRIMARY KEY, full_name text NOT NULL, email text, department text, active boolean NOT NULL DEFAULT true, source_updated_at timestamptz NOT NULL, projected_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS development_boards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL, system_id uuid, status text NOT NULL DEFAULT 'active', is_active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS development_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), number bigint GENERATED ALWAYS AS IDENTITY UNIQUE, code text UNIQUE NOT NULL DEFAULT ('DEV-' || upper(substr(gen_random_uuid()::text,1,8))), service_desk_request_id uuid NOT NULL, parent_task_id uuid REFERENCES development_tasks(id) ON DELETE CASCADE, root_task_id uuid, board_id uuid, system_id uuid, status text NOT NULL DEFAULT 'backlog' REFERENCES development_statuses(code), title text NOT NULL, description text, analyst_id uuid, developer_id uuid, priority integer NOT NULL DEFAULT 3 CHECK (priority BETWEEN 1 AND 5), development_start_date date, release_date date, planned_hours numeric(10,2) NOT NULL DEFAULT 0 CHECK (planned_hours >= 0), analytics_hours numeric(10,2) NOT NULL DEFAULT 0 CHECK (analytics_hours >= 0), development_hours numeric(10,2) NOT NULL DEFAULT 0 CHECK (development_hours >= 0), total_hours numeric(10,2) NOT NULL DEFAULT 0 CHECK (total_hours >= 0), created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (release_date IS NULL OR development_start_date IS NULL OR release_date >= development_start_date));
CREATE TABLE IF NOT EXISTS development_task_watchers (task_id uuid NOT NULL REFERENCES development_tasks(id) ON DELETE CASCADE, user_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (task_id,user_id));
CREATE TABLE IF NOT EXISTS development_task_comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), task_id uuid NOT NULL REFERENCES development_tasks(id) ON DELETE CASCADE, author_id uuid NOT NULL, comment text NOT NULL CHECK (char_length(comment) <= 500), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS outbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL UNIQUE, event_type text NOT NULL, event_version integer NOT NULL DEFAULT 1, aggregate_type text NOT NULL, aggregate_id text NOT NULL, correlation_id text NOT NULL, payload jsonb NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, attempts integer NOT NULL DEFAULT 0, last_error text);
CREATE TABLE IF NOT EXISTS processed_events (event_id uuid NOT NULL, consumer text NOT NULL, processed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (event_id, consumer));
CREATE INDEX IF NOT EXISTS development_tasks_status_idx ON development_tasks(board_id,status,updated_at DESC);
